<h3 id="tag-props" tabindex="-1"><a class="header-anchor" href="#tag-props"><span><code v-pre>&lt;Tag&gt;</code> Props</span></a></h3>
<table>
<thead>
<tr>
<th>属性</th>
<th>说明</th>
<th>类型</th>
<th>默认值</th>
</tr>
</thead>
<tbody>
<tr>
<td>color</td>
<td>标签的颜色</td>
<td><code v-pre>'red' | 'orangered' | 'orange' | 'gold' | 'lime' | 'green' | 'cyan' | 'blue' | 'brand' | 'purple' | 'pinkpurple' | 'magenta' | 'gray'</code></td>
<td>-</td>
</tr>
<tr>
<td>status</td>
<td>标签状态色（与 Button 对齐，与 <code v-pre>color</code> 互斥，<code v-pre>color</code> 优先）</td>
<td><code v-pre>'primary' | 'secondary' | 'tertiary' | 'info' | 'success' | 'warning' | 'danger'</code></td>
<td>-</td>
</tr>
<tr>
<td>variant</td>
<td>标签变体（与 Button 对齐）</td>
<td><code v-pre>'default' | 'outline'</code></td>
<td><code v-pre>'default'</code></td>
</tr>
<tr>
<td>size</td>
<td>标签的大小</td>
<td><code v-pre>'xs' | 'sm' | 'md' | 'lg' | 'xl'</code></td>
<td><code v-pre>'md'</code></td>
</tr>
<tr>
<td>visible <strong>(v-model)</strong></td>
<td>标签是否可见</td>
<td><code v-pre>boolean</code></td>
<td>-</td>
</tr>
<tr>
<td>default-visible</td>
<td>标签默认是否可见</td>
<td><code v-pre>boolean</code></td>
<td><code v-pre>true</code></td>
</tr>
<tr>
<td>loading</td>
<td>标签是否为加载中状态</td>
<td><code v-pre>boolean</code></td>
<td><code v-pre>false</code></td>
</tr>
<tr>
<td>closable</td>
<td>标签是否可关闭</td>
<td><code v-pre>boolean</code></td>
<td><code v-pre>false</code></td>
</tr>
<tr>
<td>checkable</td>
<td>标签是否可选中</td>
<td><code v-pre>boolean</code></td>
<td><code v-pre>false</code></td>
</tr>
<tr>
<td>checked <strong>(v-model)</strong></td>
<td>标签是否选中（标签可选中时可用）</td>
<td><code v-pre>boolean</code></td>
<td>-</td>
</tr>
<tr>
<td>default-checked</td>
<td>标签默认选中状态（标签可选中时可用）</td>
<td><code v-pre>boolean</code></td>
<td><code v-pre>true</code></td>
</tr>
</tbody>
</table>
